config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	supervisor(supervisor)
	stock_agent(stock_agent)
	stock_tools(stock_tools)
	news_agent(news_agent)
	news_tools(news_tools)
	finish(finish)
	__end__([<p>__end__</p>]):::last
	__start__ --> supervisor;
	stock_tools --> stock_agent;
	news_tools --> news_agent;
	finish --> __end__;
	supervisor -.-> stock_agent;
	supervisor -.-> news_agent;
	supervisor -.-> finish;
	stock_agent -.-> stock_tools;
	stock_agent -.-> supervisor;
	news_agent -.-> news_tools;
	news_agent -.-> supervisor;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
